// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        // give the contract some ETH so the selfdestruct payout is observable
        vm.deal(address(c), 1 ether);
        uint256 contractBalBefore = address(c).balance;
        uint256 actorBalBefore = actor.balance;

        vm.prank(actor);
        bool ok;
        try c.sudicideAnyone() { ok = true; } catch { ok = false; }

        if (ok) {
            // Rule: on success, ALL of c's ETH must have gone to msg.sender,
            // and the contract must be destroyed with zero balance.
            assertTrue(
                address(c).balance == 0 && actor.balance == actorBalBefore + contractBalBefore,
                "payout must go to the caller"
            );
        } else {
            // non-owner calls must revert and leave state untouched
            assertTrue(
                address(c).balance == contractBalBefore,
                "failed call must not move funds"
            );
        }
    }
}

