pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        // wide admissible domain: any non-zero actor, any balance for the contract
        vm.assume(actor != address(0));
        amount = bound(amount, 0, type(uint256).max / 2);

        // give the contract value so the selfdestruct payout is observable
        vm.deal(address(c), amount);

        // drive c through sudicideAnyone as an arbitrary fuzzed caller
        bool ok;
        vm.prank(actor);
        try c.sudicideAnyone() { ok = true; } catch { ok = false; }

        // general rule: the call succeeds EXACTLY WHEN the caller is the owner.
        // The reference P satisfies this for every input (require enforces it, and
        // the payout then necessarily goes to that same caller).
        // The mutant M breaks it: it pays out to the owner even when some other
        // caller invokes sudicideAnyone, so for a non-owner actor M yields
        // ok == true while actor != c.smartfix_owner() — the assertion fails.
        assertTrue(ok == (actor == c.smartfix_owner()));
    }
}

