pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public { c = new C(); owner = c.smartfix_owner(); }

    function testFuzz_property(address actor, uint256 amount) public {
        // 1. wide admissible domain: any non-zero actor, any ETH amount
        vm.assume(actor != address(0));
        amount = bound(amount, 1, type(uint128).max);

        // 2. fund the contract itself; fund the caller so it can be observed
        vm.deal(address(c), amount);
        vm.deal(actor, 1 ether);
        uint256 callerBefore = actor.balance;
        uint256 contractBefore = address(c).balance;

        // 3. drive the boundary call, observing revert behaviour
        vm.prank(actor);
        bool ok;
        try c.sudicideAnyone() { ok = true; } catch { ok = false; }

        // 4. general rule: success iff caller is owner; on success the CALLER
        //    receives c's entire balance (selfdestruct pays msg.sender) and c is emptied.
        assertTrue(
            ok == (actor == owner) &&
            (!ok || (actor.balance == callerBefore + contractBefore && address(c).balance == 0)),
            "destroy pays caller, not owner"
        );
    }
}

