pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        // WIDE domain: any non-contract-fuzzed actor, any fundable amount.
        vm.assume(actor != address(c));
        amount = bound(amount, 0, 1e30);

        // Fund c so a successful selfdestruct has value to move.
        vm.deal(address(c), amount);
        uint256 cBefore = address(c).balance;
        uint256 actorBefore = actor.balance;

        // Drive the entry point with the fuzzed actor.
        bool ok;
        vm.prank(actor);
        try c.sudicideAnyone() {
            ok = true;
        } catch {
            ok = false;
        }

        // Universal rule: either the call reverts, or the CALLER is paid
        // c's entire balance and c is emptied.
        assertTrue(
            !ok || (actor.balance == actorBefore + cBefore && address(c).balance == 0),
            "successful selfdestruct must pay the caller, not the owner"
        );
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        // Admissible domain: any actor, any positive endowment for c.
        vm.assume(actor != address(0));
        amount = bound(amount, 1, type(uint256).max / 2);

        // Endow the contract under test so the selfdestruct payout is observable.
        vm.deal(address(c), amount);
        uint256 callerBefore = actor.balance;
        uint256 contractBefore = address(c).balance;

        vm.prank(actor);
        bool ok;
        try c.sudicideAnyone() { ok = true; } catch { ok = false; }

        // General rule: a successful selfdestruct pays the CALLER the contract's
        // entire balance (and the contract ends empty); otherwise the call must
        // have reverted and nothing may have moved. The mutant instead pays the
        // owner's address, so a successful call whose proceeds do not arrive at
        // the caller breaks this rule.
        assertTrue(!ok || (actor.balance == callerBefore + contractBefore && address(c).balance == 0));
    }
}

contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }
  function test() public {
    bool reverted = false;
    try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
    assert(reverted);
  }
  receive() external payable {}
  fallback() external {}
}

