contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(c.smartfix_owner() == msg.sender);
        require(address(this).balance >= amount);
        c.sudicideAnyone();
        assert(c.smartfix_owner() == address(0) && amount >= 0);
    }
    receive() external payable {}
